/**
 * @method
 * @name foxbit#createOrder
 * @description Create an order with the specified characteristics
 * @see https://docs.foxbit.com.br/rest/v3/#tag/Trading/operation/OrdersController_create
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market', 'limit', 'stop_market', 'stop_limit', 'instant'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much you want to trade in units of the base currency
 * @param {float} [price] the price at which the order is to be fullfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.timeInForce] "GTC", "FOK", "IOC", "PO"
 * @param {float} [params.triggerPrice] The time in force for the order. One of GTC, FOK, IOC, PO. See .features or foxbit's doc to see more details.
 * @param {bool} [params.postOnly] true or false whether the order is post-only
 * @param {string} [params.clientOrderId] a unique identifier for the order
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Foxbit) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Foxbit) createOrderBody(ch chan any, symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var typeValue string = strings.ToUpper(typeVar)
	if (typeValue != "LIMIT") && (typeValue != "MARKET") && (typeValue != "STOP_MARKET") && (typeValue != "STOP_LIMIT") && (typeValue != "INSTANT") {
		panic(InvalidOrder("Invalid order type: " + typeValue + ". Must be one of: limit, market, stop_market, stop_limit, instant."))
	}
	var timeInForce *string = this.SafeStringUpper(params, "timeInForce")
	var postOnly *bool = this.SafeBool(params, "postOnly", false)
	var triggerPrice *float64 = this.SafeNumber(params, "triggerPrice")
	this.CheckRequiredArgument("createOrder", side, "side")
	var request map[string]any = map[string]any{
		"market_symbol": market["id"],
		"side":          strings.ToUpper(side),
		"type":          typeValue,
	}
	if (typeValue == "STOP_MARKET") || (typeValue == "STOP_LIMIT") {
		if triggerPrice == nil {
			panic(InvalidOrder("Invalid order type: " + typeValue + ". Must have triggerPrice."))
		}
	}
	if timeInForce != nil {
		if timeInForce != nil && *timeInForce == "PO" {
			request["post_only"] = true
		} else {
			request["time_in_force"] = timeInForce
		}
	}
	if postOnly != nil && *postOnly == true {
		request["post_only"] = true
	}
	if triggerPrice != nil {
		request["stop_price"] = this.PriceToPrecision(symbol, triggerPrice)
	}
	if typeValue == "INSTANT" {
		request["amount"] = this.PriceToPrecision(symbol, amount)
	} else {
		request["quantity"] = this.AmountToPrecision(symbol, amount)
	}
	if (typeValue == "LIMIT") || (typeValue == "STOP_LIMIT") {
		request["price"] = this.PriceToPrecision(symbol, price)
	}
	var clientOrderId *string = this.SafeString(params, "clientOrderId")
	if clientOrderId != nil {
		request["client_order_id"] = clientOrderId
	}
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"timeInForce", "postOnly", "triggerPrice", "clientOrderId"})

	var response map[string]any = (<-this.V3PrivatePostOrders(this.Extend(request, paramsOmitted))).Checked()

	// {
	//     "id": 1234567890,
	//     "sn": "OKMAKSDHRVVREK",
	//     "client_order_id": "451637946501"
	// }
	ch <- this.ParseOrder(response, market)
	return nil
}

/**
 * @method
 * @name foxbit#createOrders
 * @description create a list of trade orders
 * @see https://docs.foxbit.com.br/rest/v3/#tag/Trading/operation/createBatch
 * @param {Array} orders list of orders to create, each object should contain the parameters required by createOrder, namely symbol, type, side, amount, price and params
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Foxbit) CreateOrdersAsync(orders any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.createOrdersBody(ch, orders, optionalArgs...)
	return ch
}
func (this *Foxbit) createOrdersBody(ch chan any, orders any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var ordersRequests []any = []any{}
	for i := 0; i < GetArrayLength(orders); i++ {
		var order map[string]any = SafeMapTyped(orders, i)
		var symbol *string = this.SafeString(order, "symbol")
		var market map[string]any = this.Market(symbol)
		var typeVar *string = this.SafeStringUpper(order, "type")
		var orderParams any = this.SafeDict(order, "params", map[string]any{})
		if (typeVar == nil || *typeVar != "LIMIT") && (typeVar == nil || *typeVar != "MARKET") && (typeVar == nil || *typeVar != "STOP_MARKET") && (typeVar == nil || *typeVar != "STOP_LIMIT") && (typeVar == nil || *typeVar != "INSTANT") {
			panic(InvalidOrder(Add(Add("Invalid order type: ", typeVar), ". Must be one of: limit, market, stop_market, stop_limit, instant.")))
		}
		var timeInForce *string = this.SafeStringUpper(orderParams, "timeInForce")
		var postOnly *bool = this.SafeBool(orderParams, "postOnly", false)
		var triggerPrice *float64 = this.SafeNumber(orderParams, "triggerPrice")
		var request map[string]any = map[string]any{
			"market_symbol": market["id"],
			"side":          this.SafeStringUpper(order, "side"),
			"type":          typeVar,
		}
		if (typeVar != nil && *typeVar == "STOP_MARKET") || (typeVar != nil && *typeVar == "STOP_LIMIT") {
			if triggerPrice == nil {
				panic(InvalidOrder(Add(Add("Invalid order type: ", typeVar), ". Must have triggerPrice.")))
			}
		}
		if timeInForce != nil {
			if timeInForce != nil && *timeInForce == "PO" {
				request["post_only"] = true
			} else {
				request["time_in_force"] = timeInForce
			}
			Remove(orderParams, "timeInForce")
		}
		if postOnly != nil && *postOnly == true {
			request["post_only"] = true
			Remove(orderParams, "postOnly")
		}
		if triggerPrice != nil {
			request["stop_price"] = this.PriceToPrecision(symbol, triggerPrice)
			Remove(orderParams, "triggerPrice")
		}
		if typeVar != nil && *typeVar == "INSTANT" {
			request["amount"] = this.PriceToPrecision(symbol, this.SafeString(order, "amount"))
		} else {
			request["quantity"] = this.AmountToPrecision(symbol, this.SafeString(order, "amount"))
		}
		if (typeVar != nil && *typeVar == "LIMIT") || (typeVar != nil && *typeVar == "STOP_LIMIT") {
			request["price"] = this.PriceToPrecision(symbol, this.SafeString(order, "price"))
		}
		ordersRequests = append(ordersRequests, this.Extend(request, orderParams))
	}
	var createOrdersRequest map[string]any = map[string]any{
		"data": ordersRequests,
	}

	response := (<-this.V3PrivatePostOrdersBatch(this.Extend(createOrdersRequest, params)))
	PanicOnError(response)
	// {
	//     "data": [
	//         {
	//         "side": "BUY",
	//         "type": "LIMIT",
	//         "market_symbol": "btcbrl",
	//         "client_order_id": "451637946501",
	//         "remark": "A remarkable note for the order.",
	//         "quantity": "0.42",
	//         "price": "250000.0",
	//         "post_only": true,
	//         "time_in_force": "GTC"
	//         }
	//     ]
	// }
	var data []any = SafeListTypedDefault(response, "data", []any{})

	ch <- this.ParseOrders(data)
	return nil
}

