func (this *Foxbit) ParseTransaction(transaction any, optionalArgs ...any) any {
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var cryptoDetails map[string]any = SafeMapTyped(transaction, "details_crypto")
	var address *string = this.SafeString2(cryptoDetails, "receiving_address", "destination_address")
	var sn *string = this.SafeString(transaction, "sn")
	var typeVar string = "withdrawal"
	if (sn != nil) && (GetValue(sn, 0) == "D") {
		typeVar = "deposit"
	}
	var fee *string = this.SafeString(transaction, "fee", "0")
	var amount *string = this.SafeString(transaction, "amount")
	var currencySymbol *string = this.SafeString(transaction, "currency_symbol")
	var actualAmount *string = amount
	var currencyCode *string = this.SafeCurrencyCode(currencySymbol)
	var status *string = this.ParseTransactionStatus(this.SafeString(transaction, "state"))
	var created_at *string = this.SafeString(transaction, "created_at")
	var timestamp any = this.ParseDate(created_at)
	var datetime *string = this.Iso8601(timestamp)
	if (fee != nil) && (amount != nil) {
		// actualAmount = amount - fee;
		actualAmount = Precise.StringSub(amount, fee)
	}
	var feeRate *string = Precise.StringDiv(fee, actualAmount)
	var feeObj map[string]any = map[string]any{
		"cost":     this.ParseNumber(fee),
		"currency": currencyCode,
		"rate":     this.ParseNumber(feeRate),
	}
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString(transaction, "sn"),
		"txid":        this.SafeString(cryptoDetails, "transaction_id"),
		"timestamp":   timestamp,
		"datetime":    datetime,
		"network":     this.SafeString(transaction, "network_code"),
		"address":     address,
		"addressTo":   address,
		"addressFrom": nil,
		"tag":         this.SafeString(transaction, "destination_tag"),
		"tagTo":       this.SafeString(transaction, "destination_tag"),
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      this.ParseNumber(amount),
		"currency":    currencyCode,
		"status":      status,
		"updated":     nil,
		"fee":         feeObj,
		"comment":     nil,
		"internal":    nil,
	}
}
func (this *Foxbit) ParseLedgerEntryType(typeVar *string) *string {
	var types map[string]any = map[string]any{
		"DEPOSITING":           "transaction",
		"WITHDRAWING":          "transaction",
		"TRADING":              "trade",
		"INTERNAL_TRANSFERING": "transfer",
		"OTHERS":               "transaction",
	}
	return this.SafeString(types, typeVar, typeVar)
}
func (this *Foxbit) ParseLedgerEntry(item any, optionalArgs ...any) any {
	// {
	//     "uuid": "f8e9f2d6-3c1e-4f2d-8f8e-9f2d6c1e4f2d",
	//     "amount": "0.0001",
	//     "balance": "0.0002",
	//     "created_at": "2021-07-01T12:00:00Z",
	//     "currency_symbol": "btc",
	//     "fee": "0.0001",
	//     "locked": "0.0001",
	//     "locked_amount": "0.0001",
	//     "reason_type": "DEPOSITING"
	// }
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var id *string = this.SafeString(item, "uuid")
	var createdAt *string = this.SafeString(item, "created_at")
	var timestamp *int64 = this.Parse8601(createdAt)
	var reasonType *string = this.SafeString(item, "reason_type")
	var typeVar *string = this.ParseLedgerEntryType(reasonType)
	var exchangeSymbol *string = this.SafeString(item, "currency_symbol")
	var currencySymbol *string = this.SafeCurrencyCode(exchangeSymbol)
	var direction string = "in"
	var amount *float64 = this.SafeNumber(item, "amount")
	var realAmount any = amount
	var balance *float64 = this.SafeNumber(item, "balance")
	var fee map[string]any = map[string]any{
		"cost":     this.SafeNumber(item, "fee"),
		"currency": currencySymbol,
	}
	if amount == nil {
		panic(ArgumentsRequired(this.Id + " parseLedgerEntry() requires a amount argument"))
	}
	if IsLessThan(amount, 0) {
		direction = "out"
		if amount == nil {
			panic(ArgumentsRequired(this.Id + " parseLedgerEntry() requires a amount argument"))
		}
		realAmount = Multiply(amount, OpNeg(1))
	}
	if balance == nil {
		panic(ExchangeError(this.Id + " parseLedgerEntry() missing balance"))
	}
	if amount == nil {
		panic(ArgumentsRequired(this.Id + " parseLedgerEntry() requires a amount argument"))
	}
	return map[string]any{
		"id":               id,
		"info":             item,
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"direction":        direction,
		"account":          nil,
		"referenceId":      nil,
		"referenceAccount": nil,
		"type":             typeVar,
		"currency":         currencySymbol,
		"amount":           realAmount,
		"before":           Subtract(balance, amount),
		"after":            balance,
		"status":           "ok",
		"fee":              fee,
	}
}
func (this *Foxbit) Sign(path string, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, []any{})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var headers map[string]any = GetArgMap(optionalArgs, 3, nil)
	_ = headers
	body := GetArg(optionalArgs, 4, nil)
	_ = body
	var version any = GetValue(api, 0)
	var urlPath any = GetValue(api, 1)
	var fullPath any = Add(Add(Add("/rest/", version), "/"), this.ImplodeParams(path, params))
	if version == "status" {
		fullPath = "/status"
		urlPath = "status"
	}
	var apiUrl *string = this.SafeString(GetValue(this.Urls, "api"), urlPath)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url any = Add(apiUrl, fullPath)
	var paramsOmitted any = this.Omit(params, this.ExtractParams(path))
	var timestamp int64 = this.Milliseconds()
	var query string = ""
	var signatureQuery string = ""
	if method == "GET" {
		var paramKeys []string = ObjectKeys(paramsOmitted)
		var paramKeysLength int = len(paramKeys)
		if paramKeysLength > 0 {
			query = this.Urlencode(paramsOmitted)
			url = Add(url, "?"+query)
		}
		for i := 0; i < len(paramKeys); i++ {
			var key string = paramKeys[i]
			var value *string = this.SafeString(paramsOmitted, key)
			if value != nil {
				signatureQuery += key + "=" + *value
			}
			if IsLessThan(i, paramKeysLength-1) {
				signatureQuery += "&"
			}
		}
	}
	var requestBody any = body
	if (method == "POST") || (method == "PUT") {
		requestBody = this.Json(paramsOmitted)
	}
	var bodyToSignature any = ""
	if requestBody != nil {
		bodyToSignature = requestBody
	}
	var headersValue map[string]any = map[string]any{
		"Content-Type":        "application/json",
		"X-FB-CLIENT":         "ccxt",
		"X-FB-CLIENT-VERSION": this.GetCcxtVersion(),
	}
	if urlPath == "private" {
		this.CheckRequiredCredentials()
		var preHash *string = SafeStringPtr(Add(Add(Add(Add(this.NumberToString(timestamp), method), fullPath), signatureQuery), bodyToSignature))
		var signature string = this.Hmac(this.Encode(preHash), this.Encode(this.Secret), sha256, "hex")
		headersValue["X-FB-ACCESS-KEY"] = this.ApiKey
		headersValue["X-FB-ACCESS-TIMESTAMP"] = this.NumberToString(timestamp)
		headersValue["X-FB-ACCESS-SIGNATURE"] = signature
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    requestBody,
		"headers": headersValue,
	}
}
func (this *Foxbit) HandleErrors(httpCode any, reason any, url any, method any, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil
	}
	var error map[string]any = SafeMapTyped(response, "error")
	var code *string = this.SafeString(error, "code")
	var details []any = SafeListTyped(error, "details")
	var message *string = this.SafeString(error, "message")
	var detailsString any = ""
	if details != nil {
		for i := 0; i < len(details); i++ {
			detailsString = Add(Add(detailsString, func() any {
				if i >= 0 && i < len(details) {
					return DerefScalar(details[i])
				}
				return nil
			}()), " ")
		}
	}
	if error != nil {
		var feedback *string = SafeStringPtr(Add(Add(Add(this.Id+" ", message), " details: "), detailsString))
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], detailsString, feedback)
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], code, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewFoxbit(userConfig map[string]any) *Foxbit {
	p := newFoxbit()
	p.Init(userConfig)
	return p
}

func (this *Foxbit) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = NewExchangeTyped(&this.Exchange)
}

